import 'react-viewer/dist/index.css'
import React from 'react'
import { connect } from 'react-redux'
import { isEqual, get, map } from 'lodash'
import PropTypes from 'prop-types'
import {
  Collapse,
  Checkbox,
  Modal,
  Spin,
  Row,
  Col,
  Radio,
  notification,
  Empty,
  Select,
  Dropdown,
  Menu,
  Icon,
  Tag
} from 'antd'

import WrappedDynamicForm from '../../../../components/dynamicForm'
import { createEditBenefitGroup } from './formData'
import { ShowBenefitGroupDataStyle } from './claimConfig.style'
import ClaimActions from '../../../redux/claims/actions'
import errorAction from '../../../../redux/error/actions'
import loadingAction from '../../../../redux/loading/actions'
import EditBenefit from './editBenefit'

const { Panel } = Collapse
const { Option } = Select

const { editBenefitGroup, benefitDetail, getConfigList, getInprogressConfig, replicateBenefitGroup, getBenefitGroup } = ClaimActions
const { resetErrorRedux } = errorAction
const { resetLoadingRedux } = loadingAction

const TSI_TYPE = ['FIXED', 'PERIODIC', 'METHOD']

const careIntegrationDataLabels = {
  col: 'Cause of Loss(COL)',
  kol: 'Kol',
  damage_type: 'Damage Type',
  payment_to: 'Payment to',
  remarks: 'Remarks',
  toi: 'TOI'
}

class ShowBenefitGroupData extends React.Component {
  constructor (props) {
    super(props)
    this.state = {
      benefitGroupData: this.props.benefitGroupData,
      groupedBenefitGroup: this.props.groupedBenefitGroup,
      editBenefitGroupModal: false,
      viewBenefitModal: false,
      selectedBenefit: [],
      benefitDetails: {},
      selectedBenefitGroup: undefined,
      showBenefitGroupDetails: false,
      showEditBenefitModal: false,
      viewConfigList: false,
      editConfig: '',
      checkedBenefitGroup: [],
      selectedBenefitGroupToReplicate: '',
      showReplicateModal: false,
      selectedPackagesToReplicate: [],
      source: ''
    }

    this.dynamicForm = React.createRef()
  }

  componentDidMount () {
    this.props.resetErrorRedux(['EDIT_BENEFIT_GROUP', 'REPLICATE_BENEFIT_GROUP'])
    this.props.resetLoadingRedux(['EDIT_BENEFIT_GROUP', 'REPLICATE_BENEFIT_GROUP'])
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      replicateBenefitGroupLoading,
      replicateBenefitGroupError,
      replicateBenefitGroupStatus,
      groupedBenefitGroup
    } = nextProps

    if (JSON.stringify(nextProps.benefitGroupData) !== JSON.stringify(this.state.benefitGroupData)) {
      this.setState({ benefitGroupData: nextProps.benefitGroupData })
    }
    if (JSON.stringify(nextProps.benefitDetails) !== JSON.stringify(this.state.benefitDetails)) {
      this.setState({ benefitDetails: nextProps.benefitDetails })
    }
    if (nextProps.editBenefitGroupStatus && nextProps.editBenefitGroupLoading === false) {
      notification[nextProps.editBenefitGroupError ? 'error' : 'success']({ message: nextProps.editBenefitGroupStatus })
      this.props.resetErrorRedux(['EDIT_BENEFIT_GROUP'])
      this.props.resetLoadingRedux(['EDIT_BENEFIT_GROUP'])
    }
    if (nextProps.editBenefitGroupError === false && nextProps.editBenefitGroupLoading === false) {
      this.setState({ editBenefitGroupModal: false })

      const wrappedInstance = this.dynamicForm.current.getWrappedInstance()
      wrappedInstance.resetFields()
      this.props.refreshData()
      this.props.resetErrorRedux(['EDIT_BENEFIT_GROUP'])
      this.props.resetLoadingRedux(['EDIT_BENEFIT_GROUP'])
    }
    if (replicateBenefitGroupLoading === false) {
      notification[replicateBenefitGroupError ? 'error' : 'success']({ message: replicateBenefitGroupStatus })
      if (replicateBenefitGroupError === false) {
        const { data } = this.props
        this.setState({ showReplicateModal: false })
        this.props.getBenefitGroup({
          query: {
            'product-key': data.product_key,
            'package-code': data.package_code
          }
        })
      }
      this.props.resetErrorRedux(['REPLICATE_BENEFIT_GROUP'])
      this.props.resetLoadingRedux(['REPLICATE_BENEFIT_GROUP'])
    }

    if (!isEqual(groupedBenefitGroup, this.state.groupedBenefitGroup)) {
      this.setState({ checkedBenefitGroup: [], groupedBenefitGroup })
    }
  }

  onEditBenefitGroup = (values) => {
    const { editBenefitGroup } = this.props
    const { selectedBenefitGroup } = this.state
    editBenefitGroup({ values, benefit_group_id: selectedBenefitGroup.id })
  }

  viewDetails = (benefitId, benefitGroupID) => {
    const { benefitDetail } = this.props

    this.setState({ viewBenefitModal: true })
    benefitDetail({ benefit_group_id: benefitGroupID, benefit_id: benefitId })
  }

  editBenefit = (benefitId, benefitGroupID) => {
    this.setState({ showEditBenefitModal: true, selectedBenefitGroupID: benefitGroupID })
    this.props.benefitDetail({ benefit_group_id: benefitGroupID, benefit_id: benefitId })
  }

  showAddConfigModal = () => {
    this.setState({ showAddConfigModal: true })
  }

  handleAddConfig = (id, source) => {
    const { data, selectedPartner } = this.props
    this.props.history.push({
      pathname: '/claims/add-config',
      state: {
        id,
        productKey: get(data, 'product_key'),
        source: source !== 'AutoFSM' ? '' : source,
        benefitSource: source,
        selectedPartner: selectedPartner
      }
    })
  }

  handleCancel = (stateName) => {
    this.setState({ [stateName]: false })
  }

  handleViewConfig = (benefitId, source) => {
    const { selectedPartner } = this.props
    this.setState({
      viewConfigList: true,
      benefitId,
      source: source !== 'AutoFSM' ? '' : source,
      benefitSource: source
    })
    this.props.getConfigList({
      query: {
        benefit_id: benefitId,
        selectedPartner: selectedPartner
      }
    })
  }

  handleEdit = () => {
    const { editConfig, benefitId, source, benefitSource } = this.state
    const { data, selectedPartner } = this.props
    if (editConfig !== '') {
      this.props.history.push({
        pathname: '/claims/add-config',
        state: {
          id: benefitId,
          configData: editConfig,
          productKey: data?.product_key,
          selectedPartner: selectedPartner,
          benefitSource,
          source
        }
      })
    } else {
      notification.error({ message: 'Please select Config' })
    }
  }

  handleCheckboxChange = (checked, value) => {
    const { checkedBenefitGroup } = this.state
    if (checked) {
      if (typeof value === 'string') {
        checkedBenefitGroup.push(value)
      } else {
        checkedBenefitGroup.push(...value)
      }
    } else {
      if (typeof value === 'string') {
        const index = checkedBenefitGroup.indexOf(value)
        if (index !== -1) checkedBenefitGroup.splice(index, 1)
      } else {
        for (let i = 0; i < value.length; i++) {
          const index = checkedBenefitGroup.indexOf(value[i])
          if (index !== -1) checkedBenefitGroup.splice(index, 1)
        }
      }
    }
    this.props.onChangeCheck(checkedBenefitGroup.filter((v, i, a) => a.indexOf(v) === i))
    this.setState({ checkedBenefitGroup: checkedBenefitGroup.filter((v, i, a) => a.indexOf(v) === i) })
  }

  handleReplicate = (id) => {
    this.setState({ selectedBenefitGroupToReplicate: id, showReplicateModal: true })
  }

  handleReplicateBG = () => {
    const { selectedBenefitGroupToReplicate, selectedPackagesToReplicate } = this.state
    this.props.replicateBenefitGroup({
      body: {
        benefit_group_ids: [selectedBenefitGroupToReplicate],
        new_package_codes: selectedPackagesToReplicate
      }
    })
  }

  renderPanelHeaderExtra = (benefitGroup) => {
    const { data = {} } = this.props
    return (
      <Row type='flex' justify='space-around'>
        <Col
          className='view text-link'
          onClick={(e) => {
            e.stopPropagation()
            this.setState({ selectedBenefitGroup: benefitGroup, showBenefitGroupDetails: true })
          }}
        >
          View
        </Col>
        <Col
          className={`edit text-link ${!get(data, 'package_code') && 'disable-link'}`}
          onClick={(e) => {
            e.stopPropagation()
            if (!get(data, 'package_code')) {
              return notification.error({ message: 'Please select package code to edit!' })
            }
            const maxClaimAmount = get(benefitGroup, 'max_claim_amount', '')
            if (isNaN(maxClaimAmount)) {
              benefitGroup.max_claim_amount_type = 'METHOD'
            } else {
              benefitGroup.max_claim_amount_type = 'FIXED'
            }
            this.setState({ editBenefitGroupModal: true, selectedBenefitGroup: benefitGroup })
          }}
        >
          Edit
        </Col>
        <Col
          className='replicate text-link'
          onClick={(e) => {
            e.stopPropagation()
            this.handleReplicate(benefitGroup.id)
          }}
        >
          Replicate
        </Col>
      </Row>
    )
  }

  benefitActionMenu = (id, benefitGroupID, source) => {
    return (
      <Menu>
        <Menu.Item>
          <Col onClick={e => {
            e.stopPropagation()
            this.viewDetails(id, benefitGroupID)
          }}
          >
            View Benefit
          </Col>
        </Menu.Item>
        <Menu.Item>
          <Col onClick={(e) => {
            e.stopPropagation()
            this.editBenefit(id, benefitGroupID)
          }}
          >
            Edit Benefit
          </Col>
        </Menu.Item>
        <Menu.Item>
          <Col onClick={(e) => {
            e.stopPropagation()
            this.handleAddConfig(id, source)
          }}
          >
            Add Config
          </Col>
        </Menu.Item>
        <Menu.Item>
          <Col onClick={e => {
            e.stopPropagation()
            this.handleViewConfig(id, source)
          }}
          >
            View Config
          </Col>
        </Menu.Item>
      </Menu>
    )
  }

  render () {
    const {
      data, benefitDetailLoading, editBenefitGroupLoading, groupedBenefitGroup,
      getConfigListLoading, configList = [], packageList = [], replicateBenefitGroupLoading,
      tsiMethods = {}, selectedPartner, selectedProduct,
      selectedPackageCode
    } = this.props
    const {
      benefitGroupData, editBenefitGroupModal, showEditBenefitModal,
      viewBenefitModal, benefitDetails, selectedBenefitGroup = {}, showBenefitGroupDetails,
      viewConfigList, checkedBenefitGroup, showReplicateModal, selectedBenefitGroupID
    } = this.state
    const { care_integration_data: careIntegrationData = {} } = benefitDetails

    const {
      is_active: isActive, name: selectedBenefitGroupName, description,
      max_claim_allowed: maxClaimAllowed, max_claim_amount: maxClaimAmount,
      max_claim_amount_type: maxClaimAmountType, benefitTSIInfo
    } = selectedBenefitGroup
    const tableData = (key, value) =>
      <Row className='table-row'>
        <Col span={12} className='table-key'>
          {key}
        </Col>
        <Col span={12}>
          {value}
        </Col>
      </Row>

    const editBenefitGroupAdditionalData = {
      package_name: data.package_name,
      product_key: data.product_key,
      insurance_provider: '',
      package_code: data.package_code
    }
    const editBenefitGroupDefaultValues = {
      is_active: isActive,
      benefit_group_name: selectedBenefitGroupName,
      description: description,
      number_of_times_claimable: maxClaimAllowed,
      total_sum_insured: !isNaN(maxClaimAmount) && maxClaimAmount,
      max_claim_amount_type: maxClaimAmountType,
      tsi_method: isNaN(maxClaimAmount) && maxClaimAmount,
      type: benefitTSIInfo?.type,
      percentage: benefitTSIInfo?.percentage,
      field: benefitTSIInfo?.field
    }
    const editBenefitGroupData = {
      tsiMethods: tsiMethods.tsi_methods,
      tsiTypes: TSI_TYPE,
      policyFormAttributes: typeof this.props.policyFormAttributes?.request === 'object'
        ? Object.keys(this.props.policyFormAttributes?.request).map((value) => ({
            display_name: value,
            slug: value
          }))
        : []
    }

    return (
      <ShowBenefitGroupDataStyle>
        {/* View Benefit Modal */}
        {
          Object.keys(benefitDetails).length > 0 &&
            <Modal
              visible={viewBenefitModal}
              title={benefitDetails.name}
              onCancel={() => this.setState({ viewBenefitModal: false })}
              okText='Edit'
              cancelText='Close'
              footer={null}
            >
              <ShowBenefitGroupDataStyle>
                <Spin spinning={!!benefitDetailLoading}>
                  <Checkbox className='checkbox' checked={benefitDetails.is_claim_active}>Active</Checkbox>
                  {tableData('Benefit Description', benefitDetails.description)}
                  {tableData('Number of times claimable', benefitDetails.max_claim_allowed)}
                  {tableData('Claim Reprocess Reject day', benefitDetails.claim_reprocess_reject_day || 0)}
                  {tableData('Claim Initiated Rejected Day', benefitDetails.claim_initiated_reject_day || 0)}
                  {tableData('Claim Initiated Reminder day', (benefitDetails.claim_initiated_reminder_days && benefitDetails.claim_initiated_reminder_days.join(', ')) || 0)}
                  {tableData('Claim Reprocess Reminder days', (benefitDetails.claim_reprocess_reminder_days && benefitDetails.claim_reprocess_reminder_days.join(', ')) || 0)}
                  {tableData('Config Selected', benefitDetails.configs.map((config) => config.display_name + ', ') || 'None')}
                  {careIntegrationData && Object.keys(careIntegrationData).map((key) => {
                    return <span key={key}>{tableData(careIntegrationDataLabels[key], careIntegrationData[key])}</span>
                  })}
                </Spin>
              </ShowBenefitGroupDataStyle>
            </Modal>
        }
        {/* View Benefit Group Modal */}
        <Modal
          visible={showBenefitGroupDetails}
          title={selectedBenefitGroup.name}
          onCancel={() => this.setState({ showBenefitGroupDetails: false })}
          footer={null}
          onOk={() => this.props.history.push({ pathname: 'edit-benefit', state: { benefitDetails: benefitDetails, benefitGroupData: benefitGroupData } })}
        >
          <ShowBenefitGroupDataStyle>
            <Checkbox checked={selectedBenefitGroup.is_active} className='checkbox'>Active</Checkbox>
            {tableData('Description', selectedBenefitGroup.description)}
            {tableData('Maximum Claim Allowed', selectedBenefitGroup.max_claim_allowed)}
            {tableData('Maximum Claim Amount', selectedBenefitGroup.max_claim_amount)}
          </ShowBenefitGroupDataStyle>
        </Modal>
        {/* Edit Benefit Group Modal */}
        <Modal
          visible={editBenefitGroupModal}
          title='Edit Benefit Group'
          width={600}
          footer={null}
          closable={false}
        >
          <Spin spinning={!!editBenefitGroupLoading}>
            <WrappedDynamicForm
              ref={this.dynamicForm}
              formData={
                createEditBenefitGroup(
                  'Edit Benefit Group',
                  editBenefitGroupAdditionalData,
                  editBenefitGroupDefaultValues,
                  editBenefitGroupData
                )
              }
              onCloseModal={() => this.setState({ editBenefitGroupModal: false })}
              onSubmit={(values) => this.onEditBenefitGroup(values)}
            />
          </Spin>
        </Modal>
        {/* Edit Benefit Modal */}
        <Modal
          title='Edit Benefit'
          visible={showEditBenefitModal}
          width={600}
          footer={null}
          onCancel={() => this.setState({ showEditBenefitModal: false })}
          packageList={packageList}
          benefitGroupData={benefitGroupData}
        >
          <Spin spinning={!!benefitDetailLoading}>
            <EditBenefit
              packageList={packageList}
              benefitDetails={benefitDetails}
              benefitGroupData={benefitGroupData}
              onCancel={this.handleCancel}
              benefitGroupID={selectedBenefitGroupID}
              selectedProduct={selectedProduct}
              selectedPartner={selectedPartner}
              selectedPackageCode={selectedPackageCode}
            />
          </Spin>
        </Modal>
        <Modal
          title='Config List'
          visible={viewConfigList}
          onCancel={() => this.setState({ viewConfigList: false })}
          okText='Edit'
          onOk={this.handleEdit}
        >
          <ShowBenefitGroupDataStyle>
            <Spin spinning={!!getConfigListLoading}>
              {
                configList.length > 0
                  ? (
                    <Radio.Group
                      onChange={(e) => {
                        this.setState({ editConfig: JSON.parse(e.target.value) })
                      }}
                      className='radio-group'
                    >
                      {
                        configList.map((config, index) => (
                          <div className='config-row' key={index}>
                            <Radio value={JSON.stringify(config)}>
                              {config.display_name}
                            </Radio>
                            {config.is_default && <Tag className='active-tag' color='#87d068'>Active</Tag>}
                          </div>
                        ))
                      }
                    </Radio.Group>
                    )
                  : (
                    <Row type='flex' justify='center'>
                      <Empty />
                    </Row>
                    )
              }
            </Spin>
          </ShowBenefitGroupDataStyle>
        </Modal>
        {/* Replicate Modal */}
        <Modal
          visible={showReplicateModal}
          title='Replicate Benefit Group'
          onCancel={() => this.setState({ showReplicateModal: false, selectedPackagesToReplicate: [] })}
          onOk={this.handleReplicateBG}
        >
          <ShowBenefitGroupDataStyle>
            <Spin spinning={!!replicateBenefitGroupLoading}>
              <Row align='middle'>
                <Col span={8}>
                  Package Codes
                </Col>
                <Col span={16}>
                  <Select
                    className='multi-select'
                    onChange={(value) => this.setState({ selectedPackagesToReplicate: value })}
                    dropdownMatchSelectWidth={false}
                    mode='multiple'
                    value={this.state.selectedPackagesToReplicate}
                  >
                    {
                      packageList.filter(({ package_code_slug: packageCodeSlug }) => selectedPackageCode !== packageCodeSlug).map(({ package_code_slug: packageCodeSlug }) => (
                        <Option key={packageCodeSlug} value={packageCodeSlug}>{packageCodeSlug}</Option>
                      ))
                    }
                  </Select>
                </Col>
              </Row>
            </Spin>
          </ShowBenefitGroupDataStyle>
        </Modal>
        {
          Object.keys(groupedBenefitGroup).map((packageCode, index) =>
            <div key={index} className='bg-container'>
              <Row type='flex' align='top'>
                <Checkbox
                  checked={map(groupedBenefitGroup[packageCode], 'id').every(val => checkedBenefitGroup.includes(val))}
                  value={packageCode}
                  onChange={(e) => this.handleCheckboxChange(e.target.checked, map(groupedBenefitGroup[packageCode], 'id'))}
                />
                <div className='package-head'>{packageCode}</div>
              </Row>
              {groupedBenefitGroup[packageCode].map((benefitGroup, index) => {
                const updatedbenefitGroup = {
                  ...benefitGroup,
                  benefitTSIInfo: benefitGroup?.max_claim_amount_type?.function
                    ? {
                        ...benefitGroup.max_claim_amount_type.function
                      }
                    : {}
                }
                return (
                  <Row type='flex' align='middle' key={`benefit-${index}`}>
                    <Checkbox
                      checked={checkedBenefitGroup.includes(updatedbenefitGroup.id)}
                      value={updatedbenefitGroup.id}
                      key={updatedbenefitGroup.id}
                      onChange={(e) => this.handleCheckboxChange(e.target.checked, updatedbenefitGroup.id)}
                    />
                    <Collapse>
                      <Panel
                        header={updatedbenefitGroup.name}
                        extra={this.renderPanelHeaderExtra(updatedbenefitGroup)}
                      >
                        {
                          updatedbenefitGroup.benefits.map(({ id, name, source = '' }, index) =>
                            <Row className='benefit-row' key={index} type='flex' justify='space-between'>
                              <Col className='heading' span={12}>{index + 1}. {name}</Col>
                              <Dropdown overlay={this.benefitActionMenu(id, get(updatedbenefitGroup, 'id'), source)}>
                                <span className='anchor ant-dropdown-link' onClick={e => e.preventDefault()}>
                                  Benefit Actions <Icon type='down' />
                                </span>
                              </Dropdown>
                            </Row>)
                        }
                        <Row type='flex' justify='center'>
                          <div className='add-benefit-wrapper' onClick={() => this.props.showCreateBenefitModal(get(updatedbenefitGroup, 'id'))}>
                            <Icon type='plus-circle' className='add-benefit-icon' /> Add Benefit
                          </div>
                        </Row>
                      </Panel>
                    </Collapse>
                  </Row>
                )
              }

              )}
            </div>
          )
        }

      </ShowBenefitGroupDataStyle>
    )
  }
}

ShowBenefitGroupData.propTypes = {
  benefitDetails: PropTypes.object.isRequired
}

ShowBenefitGroupData.defaultProps = {
  benefitDetails: {}
}

export default connect(state => ({
  benefitDetails: state.Claims.benefitDetails.benefit,
  benefitDetailLoading: state.Loading.BENEFIT_DETAIL,
  benefitDetailError: state.Error.BENEFIT_DETAIL,
  benefitDetailStatus: state.Claims.benefitDetailStatus,

  editBenefitGroupLoading: state.Loading.EDIT_BENEFIT_GROUP,
  editBenefitGroupError: state.Error.EDIT_BENEFIT_GROUP,
  editBenefitGroupStatus: state.Claims.editBenefitGroupStatus,

  getConfigListLoading: state.Loading.GET_CONFIG_LIST,
  getConfigListError: state.Error.GET_CONFIG_LIST,
  configList: state.Claims.configList,

  packageList: state.PromoDetails.packageLists,

  replicateBenefitGroupLoading: state.Loading.REPLICATE_BENEFIT_GROUP,
  replicateBenefitGroupError: state.Error.REPLICATE_BENEFIT_GROUP,
  replicateBenefitGroupStatus: state.Claims.replicateBenefitGroupStatus,

  configSearchData: state.Claims.configSearchData,
  tsiMethods: state.Claims.tsiMethods
}), {
  editBenefitGroup,
  benefitDetail,
  resetErrorRedux,
  resetLoadingRedux,
  getConfigList,
  getInprogressConfig,
  replicateBenefitGroup,
  getBenefitGroup
})(ShowBenefitGroupData)
