import 'react-viewer/dist/index.css'
import React from 'react'
import { connect } from 'react-redux'
import {
  Form, Input, Checkbox, Button, Row, Col,
  InputNumber, Select, Divider, Icon
} from 'antd'

import ClaimActions from '../../PasarApp/redux/claims/actions'

const { searchConfig } = ClaimActions
const { TextArea } = Input
const { Option } = Select

class DynamicForm extends React.Component {
  constructor (props) {
    super(props)
    this.state = {
      searchConfigResult: [],
      selectedConfig: [],
      defaultConfig: {},
      configs: {},
      createNewBenefitGroup: false,
      claimInitiatedReminderDaysError: false,
      claimInitiatedReminderDaysMessage: null,
      claimReprocessReminderDaysError: false,
      claimReprocessReminderDaysMessage: null
    }
  }

  componentDidUpdate () {
    if (this.props.searchConfigResult && (this.props.searchConfigResult !== this.state.searchConfigResult)) {
      this.setState({ searchConfigResult: this.props.searchConfigResult })
    }
  }

  checkDaysValidation = () => {
    const { form } = this.props
    let claimInitiatedRejectDayMatch = true
    let claimReprocessRejectDayMatch = true
    const claimInitiatedRejectDay = parseInt(form.getFieldValue('claim_initiated_reject_day'))
    const claimReprocessRejectDay = parseInt(form.getFieldValue('claim_reprocess_reject_day'))
    const claimInitiatedReminderDays = form.getFieldValue('claim_initiated_reminder_days')
    const claimReprocessReminderDays = form.getFieldValue('claim_reprocess_reminder_days')

    if (claimInitiatedRejectDay && claimInitiatedReminderDays) {
      Array.isArray(claimInitiatedReminderDays) && claimInitiatedRejectDayMatch && claimInitiatedReminderDays.forEach((day) => {
        if (day >= claimInitiatedRejectDay) {
          this.setState({
            claimInitiatedReminderDaysError: 'error',
            claimInitiatedReminderDaysMessage: 'Claim Initiated Reminder days should be less than Claim initiated reject days'
          })
          claimInitiatedRejectDayMatch = false
        }
      })
    }

    if (claimInitiatedRejectDay && claimInitiatedReminderDays) {
      Array.isArray(claimReprocessReminderDays) && claimReprocessRejectDayMatch && claimReprocessReminderDays.forEach((day) => {
        if (day >= claimReprocessRejectDay) {
          this.setState({
            claimReprocessReminderDaysError: 'error',
            claimReprocessReminderDaysMessage: 'Claim Reprocess Reminder days should be less than Claim reprocess reject days'
          })
          claimReprocessRejectDayMatch = false
        }
      })
    }
    if (claimInitiatedRejectDayMatch) {
      this.setState({
        claimInitiatedReminderDaysError: false,
        claimInitiatedReminderDaysMessage: null
      })
    }
    if (claimReprocessRejectDayMatch) {
      this.setState({
        claimReprocessReminderDaysError: false,
        claimReprocessReminderDaysMessage: null
      })
    }
    return claimInitiatedRejectDayMatch && claimReprocessRejectDayMatch
  }

  handleSubmit = e => {
    e.preventDefault()
    this.props.form.validateFields((err, values) => {
      if (!err && this.checkDaysValidation()) {
        const { formData, onSubmit } = this.props
        if (values?.max_claim_amount === 'automatic_calculation') {
          values = {
            ...values,
            max_claim_amount: 'automatic_calculation',
            data: {
              percentage: values.percentage,
              type: 'Y-percentage-of-X-field-from-policy',
              field: values.field
            }
          }
          delete values.percentage
          delete values.type
          delete values.field
        }
        onSubmit({ ...formData.additional_data, ...values })
      }
    })
  }

  onClose (htmlType) {
    if (htmlType === 'button') {
      this.props.form.resetFields()
      this.props.onCloseModal()
    }
  }

  onSelect = value => {
    this.setState(
      { selectedConfig: [...this.state.selectedConfig, JSON.parse(value)] },
      () => this.props.form.setFieldsValue({ configs: this.state.selectedConfig })
    )
  }

  onBlur = (e, parseToArray, attributeName) => {
    if (parseToArray) {
      const value = e.target.value
      if (value !== '') {
        const removeTrailingCommas = value.replace(/(^,)|(,$)/g, '')
        const data = removeTrailingCommas.split(',').map(function (item) {
          const trimmed = item.trim()
          return parseInt(trimmed)
        })
        this.props.form.setFieldsValue({ [attributeName]: data })
      }
    }
  }

  onChangeRadio = (e) => {
    this.setState({ defaultConfig: e.target.value })
  }

  renderFields (type, data = [], parseToArray, decorator, value, key, disabled) {
    const options = data && Array.isArray(data) ? data.map(d => <Option key={d.id}>{d.name}</Option>) : null

    switch (type) {
      case 'checkbox':
        return <Checkbox onChange={(e)=>{
          if(this.props.handleCheckboxChange){
            this.props.handleCheckboxChange(e)
          }
        }}  defaultChecked={value} />
      case 'float_input':
      case 'integer_input':
        return <InputNumber key={key} />
      case 'input':
        return (
          <Input
            onBlur={(e) => this.onBlur(e, parseToArray, decorator)}
          />
        )
      case 'textarea':
        return <TextArea />
      case 'select-default':
        return (
          <Select
            showSearch
            className='dynamic-form-select-width'
            onChange={() => this.props.form.resetFields(['max_claim_amount'])}
            placeholder='Select...'
            dropdownMatchSelectWidth={false}
            optionFilterProp='children'
            disabled={disabled}
          >
            {
              data.map((value) => (typeof value !== 'object')
                ? <Option key={value} value={value}>{value}</Option>
                : <Option key={value.label} value={value.val}>{value.label}</Option>
              )
            }
          </Select>
        )
      case 'select-tsi':
        return (
          <Select
            showSearch
            className='dynamic-form-select-width'
            placeholder='Select...'
            optionFilterProp='children'
            dropdownMatchSelectWidth={false}
          >
            {
              data.map(({ slug, display_name: displayName }) => <Option key={slug} value={slug}>{displayName}</Option>)
            }
          </Select>
        )
      case 'select':
        return (
          <Select
            showSearch
            className='dynamic-form-select-width'
            placeholder='Select benefit group'
            optionFilterProp='children'
            onSelect={() => {
              this.setState({ createNewBenefitGroup: false })
            }}
            filterOption={(input, option) =>
              option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
            dropdownRender={menu => (
              <div>
                {menu}
                <Divider style={{ margin: '4px 0' }} />
                <div
                  style={{ padding: '4px 8px', cursor: 'pointer' }}
                  onMouseDown={e => e.preventDefault()}
                  onClick={() => {
                    this.setState({ createNewBenefitGroup: true })
                    this.props.form.setFieldsValue({ [decorator]: 'create_new' })
                  }}
                >
                  <Icon type='plus' /> Create New
                </div>
              </div>
            )}
          >
            {options}
          </Select>
        )
      default:
        return <Input />
    }
  }

  resetForm = () => {
    this.props.form.resetFields()
  }

  checkConditionCheck =(condition) => {
    const { form } = this.props
    let flag = true
    for (let item = 0; item < condition.length; item++) {
      const { key, value } = condition[item]

      if (form.getFieldValue(key) !== value) {
        flag = false
        break
      }
    }
    return flag
  }

  render () {
    const { formData, form } = this.props
    const {
      createNewBenefitGroup, claimInitiatedReminderDaysError,
      claimInitiatedReminderDaysMessage, claimReprocessReminderDaysError,
      claimReprocessReminderDaysMessage
    } = this.state
    const { getFieldDecorator } = form
    const formItemLayout = {
      labelCol: {
        xs: { span: 24 },
        sm: { span: 10 }
      },
      wrapperCol: {
        xs: { span: 24 },
        sm: { span: 12 }
      },
      layout: 'vertical'
    }

    return (
      <Form title={formData.heading} {...formItemLayout} onSubmit={this.handleSubmit}>
        {
          formData.fields.map(({ condition, label, decorator, help, required, value, data, type, parseToArray, rules, disabled }, key) =>
            ((!condition) || (condition && condition.length && this.checkConditionCheck(condition))) &&
            (
              <Form.Item
                label={label}
                key={`form-items-${label}`}
                help={
                (decorator === 'claim_initiated_reminder_days' && claimInitiatedReminderDaysMessage) ||
                (decorator === 'claim_reprocess_reminder_days' && claimReprocessReminderDaysMessage) ||
                help
              }
                validateStatus={
                (decorator === 'claim_initiated_reminder_days' && claimInitiatedReminderDaysError) ||
                (decorator === 'claim_reprocess_reminder_days' && claimReprocessReminderDaysError) ||
                null
              }
              >
                {getFieldDecorator(decorator, {
                  rules: [
                    { required: required, message: 'Field cannot be empty!' },
                    ...(rules && rules.length ? rules : [])
                  ],
                  valuePropName: type === 'checkbox' ? 'checked' : 'value',
                  initialValue: type === 'checkbox' && !value ? false : value
                }
                )(
                  this.renderFields(type, data, parseToArray, decorator, value, key, disabled)
                )}
              </Form.Item>
            )
          )
        }
        {
          createNewBenefitGroup && (
            <>
              <Form.Item label='Benefit Group Name'>
                {getFieldDecorator('benefit_group_name', {
                  rules: [{ required: true, message: 'Field cannot be empty!' }]
                })(
                  <Input />
                )}
              </Form.Item>
              <Form.Item label='Benefit Group TSI'>
                {getFieldDecorator('benefit_group_tsi', {
                  rules: [{ required: true, message: 'Field cannot be empty!' }]
                })(
                  <InputNumber />
                )}
              </Form.Item>
              <Form.Item label='Benefit Group Number of times claimable'>
                {getFieldDecorator('benefit_group_number_of_times_claimable', {
                  rules: [{ required: true, message: 'Field cannot be empty!' }]
                })(
                  <InputNumber />
                )}
              </Form.Item>
              <Divider />
            </>
          )
        }
        <Row
          justify='space-evenly'
          align='middle'
          type='flex'
        >
          {
            formData.buttons.map((button, index) =>
              <Col offset={6} key={`form-btn-${index}`}>
                <Button type={button.type} htmlType={button.htmlType} onClick={() => this.onClose(button.htmlType)}>
                  {button.label}
                </Button>
              </Col>
            )
          }
        </Row>
      </Form>
    )
  }
}

const WrappedDynamicForm = Form.create()(DynamicForm)

export default connect(state => ({
  searchConfigResult: state.Claims.searchConfigResult.configs
}), {
  searchConfig
},
null,
{ withRef: true }
)(WrappedDynamicForm)
