import 'react-viewer/dist/index.css'
import React from 'react'
import { connect } from 'react-redux'
import { get, isEqual, groupBy } from 'lodash'
import queryString from 'query-string'
import { Form, Button, Select, Row, Modal, Spin, Upload, notification, Result } from 'antd'

import { ClaimConfigStyle } from './claimConfig.style'
import PolicyActions from '../../../../redux/policy/actions'
import promoAction from '../../../redux/promo/actions'
import ClaimActions from '../../../redux/claims/actions'
import ShowBenefitGroupData from './showBenefitGroupData'
import WrappedDynamicForm from '../../../../components/dynamicForm'
import { createEditBenefitGroup } from './formData'
import errorAction from '../../../../redux/error/actions'
import loadingAction from '../../../../redux/loading/actions'
import CreateBenefit from './createBenefit'
import queryBuilder from '../../../../helpers/querySearchBuilder'

const { getPackageList } = promoAction
const { getProducts } = PolicyActions
const {
  getBenefitGroup, addBenefitGroup, updateClaimConfigData,
  exportBenefitGroup, importBenefitGroup, getTSIMethods, resetConfigDumpId, getPolicyFormAttributes
} = ClaimActions
const { Option } = Select
const { resetErrorRedux } = errorAction
const { resetLoadingRedux } = loadingAction

const TSI_TYPE = ['FIXED', 'PERIODIC', 'METHOD']

class ClaimsConfig extends React.Component {
  constructor (props) {
    super(props)
    this.state = {
      selectedProduct: undefined,
      selectedPackageCode: undefined,
      selectedPackageName: undefined,
      selectedPartner: null,
      benefitGroupData: [],
      groupedBenefitGroup: {},
      createBenefitGroupModal: false,
      checkedList: [],
      showCreateBenefitModal: false,
      submit: false
    }
  }

  componentDidMount () {
    const { location = {} } = this.props.history

    if (location.search) {
      const values = queryString.parse(location.search)
      this.setState({
        selectedProduct: values['product-key'],
        selectedPackageCode: values['package-code'],
        selectedPackageName: values['package-name'],
        selectedPartner: values.partner
      })
      this.props.getPackageList(values['product-key'])
      this.props.updateClaimConfigData({ productKey: values['product-key'] })
      this.setState({ submit: true })
      this.props.getBenefitGroup({
        query: {
          ...values
        }
      })
      this.props.resetConfigDumpId()
    }

    // To disabled submit button at the beginning.
    this.props.form.validateFields()
    this.props.getProducts()
    this.props.getTSIMethods()
    this.props.resetErrorRedux(['ADD_BENEFIT_GROUP', 'EXPORT_BENEFIT_GROUP', 'IMPORT_BENEFIT_GROUP'])
    this.props.resetLoadingRedux(['ADD_BENEFIT_GROUP', 'EXPORT_BENEFIT_GROUP', 'IMPORT_BENEFIT_GROUP'])

    this.getPolicyFormAttributes()
  }

  componentDidUpdate (prevProps, prevState) {
    if (prevState.selectedProduct !== this.state.selectedProduct) {
      this.getPolicyFormAttributes()
    }
  }

  getPolicyFormAttributes () {
    this.props.getPolicyFormAttributes({
      query: {
        product_key: this.state.selectedProduct
      }
    })
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      addBenefitGroupLoading,
      addBenefitGroupError,
      addBenefitGroupStatus
    } = nextProps
    const { selectedProduct, selectedPackageCode, showCreateBenefitModal } = this.state
    const { location = {} } = this.props.history

    if (!isEqual(nextProps.benefitGroupData, this.state.benefitGroupData)) {
      const groupedBenefitGroup = groupBy(nextProps.benefitGroupData, 'package_code')
      this.setState({ benefitGroupData: nextProps.benefitGroupData, groupedBenefitGroup })
    }
    if (!showCreateBenefitModal && addBenefitGroupLoading === false) {
      if (addBenefitGroupError === false) {
        this.props.getBenefitGroup({ query: { 'product-key': selectedProduct, 'package-code': selectedPackageCode } })
        this.setState({ createBenefitGroupModal: false })
      }
      notification[nextProps.addBenefitGroupError ? 'error' : 'success']({ message: addBenefitGroupStatus })
      this.props.resetErrorRedux(['ADD_BENEFIT_GROUP'])
      this.props.resetLoadingRedux(['ADD_BENEFIT_GROUP'])
    }

    if (nextProps.exportBenefitGroupLoading === false) {
      notification[nextProps.exportBenefitGroupError ? 'error' : 'success']({ message: nextProps.exportBenefitGroupStatus })
      this.props.resetLoadingRedux(['EXPORT_BENEFIT_GROUP'])
      this.props.resetErrorRedux(['EXPORT_BENEFIT_GROUP'])
    }

    if (nextProps.importBenefitGroupLoading === false) {
      notification[nextProps.importBenefitGroupError ? 'error' : 'success']({ message: nextProps.importBenefitGroupStatus })
      if (!nextProps.importBenefitGroupError) {
        const values = queryString.parse(location.search)
        this.props.getBenefitGroup({
          query: {
            ...values
          }
        })
      }
      this.props.resetLoadingRedux(['IMPORT_BENEFIT_GROUP'])
      this.props.resetErrorRedux(['IMPORT_BENEFIT_GROUP'])
    }

    if (nextProps.benefitUpdateError === false && nextProps.benefitUpdateLoading === false) {
      this.props.getBenefitGroup({ query: { 'product-key': selectedProduct, 'package-code': selectedPackageCode } })
    }
  }

  hasErrors (fieldsError) {
    return Object.keys(fieldsError).some(field => fieldsError[field])
  }

  handleSelectProduct = e => {
    if (!e) {
      return this.handleReset()
    }
    const selectedProduct = JSON.parse(e)
    const productKey = selectedProduct.name || ''
    this.props.updateClaimConfigData({ productKey: productKey, partner: selectedProduct.partner })
    this.props.getPackageList(productKey)
    this.setState({ selectedProduct: productKey, selectedPackageCode: undefined, selectedPartner: selectedProduct.partner }, () => this.handleSubmit())
    this.props.form.setFieldsValue({ package: undefined })
  }

  handleSelectPackage = e => {
    let data = {}
    if (e) {
      data = JSON.parse(e)
    }
    this.setState({
      selectedPackageCode: get(data, 'package_code_slug'),
      selectedPackageName: get(data, 'package_name')
    }, () => this.handleSubmit())
  }

  handleReset = () => {
    this.props.form.setFieldsValue({ product: undefined, package: undefined })
    this.props.history.replace({ pathname: '/claims/onboarding', search: '' })
    this.setState({ submit: false, selectedProduct: undefined, selectedPackageCode: undefined, selectedPackageName: undefined })
  }

  handleSubmit = () => {
    this.props.form.validateFields((err, values) => {
      if (!err) {
        const { selectedPackageName, selectedProduct, selectedPartner } = this.state
        const data = {
          'product-key': selectedProduct,
          'package-code': values.package && JSON.parse(values.package).package_code_slug,
          'package-name': selectedPackageName,
          partner: selectedPartner
        }
        const query = queryBuilder(data)
        this.setState({ submit: true, checkedList: [] })
        this.props.history.replace({ pathname: '/claims/onboarding', search: query })
        this.props.getBenefitGroup({
          query: {
            ...data
          }
        })
      }
    })
  }

  refreshData = () => {
    const { selectedPackageCode, selectedProduct } = this.state
    this.props.getBenefitGroup({ query: { 'product-key': selectedProduct, 'package-code': selectedPackageCode } })
  }

  handleChangeCheck = val => {
    this.setState({ checkedList: val })
  }

  handleAddBenefitGroup = value => {
    this.props.addBenefitGroup(value)
  }

  handleExport = () => {
    const { checkedList } = this.state
    this.props.exportBenefitGroup({
      body: {
        benefit_group_ids: checkedList
      }
    })
  }

  handleUpload = file => {
    const reader = new FileReader()

    reader.onload = e => {
      const result = JSON.parse(e.target.result)
      this.props.importBenefitGroup({
        body: {
          ...result
        }
      })
    }
    reader.readAsText(file)

    return false
  }

  handleCancel = (stateName) => {
    this.setState({ [stateName]: false })
  }

  render () {
    const { tsiMethods = {} } = this.props
    const { products, packageList, getBenefitGroupLoading, addBenefitGroupLoading, importBenefitGroupLoading } = this.props
    const {
      selectedProduct, selectedPackageName, selectedPackageCode, groupedBenefitGroup,
      benefitGroupData, createBenefitGroupModal, checkedList, showCreateBenefitModal, submit, selectedBenefitGroupID,
      selectedPartner
    } = this.state

    const { getFieldDecorator, getFieldError, isFieldTouched } = this.props.form
    const productError = isFieldTouched('product') && getFieldError('product')
    const packageError = isFieldTouched('package') && getFieldError('package')

    return (
      <ClaimConfigStyle>
        {/* Create Benefit Group Modal */}
        <Modal
          visible={createBenefitGroupModal}
          title='Add Benefit Group'
          width={600}
          footer={null}
          closable={false}
        >
          <Spin spinning={!!addBenefitGroupLoading}>
            <WrappedDynamicForm
              formData={
                createEditBenefitGroup(
                  'Add Benefit Group',
                  { package_name: selectedPackageName, product_key: selectedProduct, insurance_provider: '', package_code: selectedPackageCode },
                  { is_active: true },
                  {
                    tsiMethods: tsiMethods.tsi_methods,
                    tsiTypes: TSI_TYPE,
                    // policyFormAttributes: tsiMethods.tsi_methods
                    policyFormAttributes: typeof this.props.policyFormAttributes?.request === 'object'
                      ? Object.keys(this.props.policyFormAttributes?.request).map((value) => ({
                          display_name: value,
                          slug: value
                        }))
                      : []
                  }
                )
              }
              onCloseModal={() => this.setState({ createBenefitGroupModal: false })}
              onSubmit={this.handleAddBenefitGroup}
            />
          </Spin>
        </Modal>
        {/* Create Benefit */}
        <Modal
          visible={showCreateBenefitModal}
          title='Create Benefit'
          footer={null}
          closable={false}
          width={700}
        >
          <CreateBenefit
            packageList={packageList}
            benefitGroupData={benefitGroupData}
            selectedPackage={selectedPackageName}
            selectedProduct={selectedProduct}
            selectedPartner={selectedPartner}
            selectedPackageCode={selectedPackageCode}
            selectedBenefitGroupID={selectedBenefitGroupID}
            onCancel={this.handleCancel}
            showCreateBenefitModal={showCreateBenefitModal}
          />
        </Modal>
        <Row type='flex' justify='end' className='export-container'>
          <Upload
            accept='.json'
            showUploadList={false}
            beforeUpload={(data) => this.handleUpload(data)}
          >
            <Button
              type='default'
              className='import'
              loading={!!importBenefitGroupLoading}
            >
              Import Benefit Group
            </Button>
          </Upload>
          <Button
            type='default'
            className='export'
            disabled={!checkedList.length}
            onClick={this.handleExport}
          >
            Export Benefit Group
          </Button>
        </Row>
        <Form layout='inline' className='search-form' hideRequiredMark onReset={this.handleReset}>
          <Form.Item label='Product' validateStatus={productError ? 'error' : ''} help={productError || ''}>
            {getFieldDecorator('product', {
              initialValue: JSON.stringify(products.find((d) => selectedProduct === d.name && d.partner === selectedPartner))
            })(
              <Select
                showSearch
                style={{ width: 200 }}
                placeholder='Select product'
                onChange={this.handleSelectProduct}
                dropdownMatchSelectWidth={false}
                allowClear
                filterOption={(input, option) => option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
              >
                {
                  products && products.map((product) => <Option key={product.id} value={JSON.stringify(product)} data-partner={product}>{product.display_name}</Option>)
                }
              </Select>
            )}
          </Form.Item>
          <Form.Item label='Package' validateStatus={packageError ? 'error' : ''} help={packageError || ''}>
            {getFieldDecorator('package', {
              initialValue: JSON.stringify(packageList?.find((p) => p.package_code === selectedPackageCode))
            })(
              <Select
                showSearch
                allowClear
                disabled={selectedProduct === undefined}
                style={{ width: 200 }}
                placeholder='Select a package'
                onChange={this.handleSelectPackage}
                optionFilterProp='children'
                dropdownMatchSelectWidth={false}
              >
                {
                  packageList && packageList.map((item, index) =>
                    <Option value={JSON.stringify(item)} key={`package-${index}`}>
                      {item.package_name || item.package_code} {item.package_code_slug && `(${item.package_code_slug})`}
                    </Option>)
                }
              </Select>
            )}
          </Form.Item>
          <Form.Item>
            <Button type='danger' htmlType='reset'>
              Clear Filter
            </Button>
          </Form.Item>
        </Form>
        {selectedProduct && selectedPackageCode &&
          <Row type='flex' className='create-row' justify='end'>
            <Button
              type='primary'
              onClick={() =>
                this.setState({ createBenefitGroupModal: true })}
            >
              Create Benefit Group
            </Button>
          </Row>}
        <Spin spinning={!!getBenefitGroupLoading} tip='Loading...'>
          {
            submit
              ? (benefitGroupData && benefitGroupData.length > 0)
                  ? <ShowBenefitGroupData
                      history={this.props.history}
                      benefitGroupData={benefitGroupData}
                      groupedBenefitGroup={groupedBenefitGroup}
                      selectedPartner={selectedPartner}
                      selectedProduct={selectedProduct}
                      selectedPackageCode={selectedPackageCode}
                      data={{ package_name: selectedPackageName, product_key: selectedProduct, package_code: selectedPackageCode }}
                      refreshData={this.refreshData}
                      onChangeCheck={this.handleChangeCheck}
                      policyFormAttributes={this.props.policyFormAttributes}
                      showCreateBenefitModal={benfitGroupID => this.setState({ showCreateBenefitModal: true, selectedBenefitGroupID: benfitGroupID })}
                    />
                  : <Result
                      status='404'
                      title='No Benefit Group Found'
                      subTitle='Please select another product-package combination or create one.'
                    />
              : null
          }
        </Spin>
      </ClaimConfigStyle>
    )
  }
}

const WrappedClaimsConfig = Form.create()(ClaimsConfig)

export default connect(state => ({
  products: state.Insurance.products,
  packageList: state.PromoDetails.packageLists,
  benefitGroupData: state.Claims.benefitGroupData,
  getBenefitGroupLoading: state.Loading.GET_BENEFIT_GROUP,
  getBenefitGroupError: state.Error.GET_BENEFIT_GROUP,
  addBenefitGroupLoading: state.Loading.ADD_BENEFIT_GROUP,
  addBenefitGroupError: state.Error.ADD_BENEFIT_GROUP,
  addBenefitGroupStatus: state.Claims.addBenefitGroupStatus,

  importBenefitGroupStatus: state.Claims.importBenefitGroupStatus,
  importBenefitGroupLoading: state.Loading.IMPORT_BENEFIT_GROUP,
  importBenefitGroupError: state.Error.IMPORT_BENEFIT_GROUP,

  exportBenefitGroupStatus: state.Claims.exportBenefitGroupStatus,
  exportBenefitGroupLoading: state.Loading.EXPORT_BENEFIT_GROUP,
  exportBenefitGroupError: state.Error.EXPORT_BENEFIT_GROUP,

  benefitUpdateLoading: state.Loading.BENEFIT_UPDATE,
  benefitUpdateError: state.Error.BENEFIT_UPDATE,

  tsiMethods: state.Claims.tsiMethods,

  claimConfigData: state.Claims.claimConfigData,

  policyFormAttributes: state.Claims.policyFormAttributes
}), {
  getProducts,
  getPackageList,
  getBenefitGroup,
  addBenefitGroup,
  resetErrorRedux,
  resetLoadingRedux,
  exportBenefitGroup,
  importBenefitGroup,
  getTSIMethods,
  resetConfigDumpId,
  updateClaimConfigData,
  getPolicyFormAttributes
})(WrappedClaimsConfig)
