import 'react-viewer/dist/index.css'
import React from 'react'
import { connect } from 'react-redux'
import { Form, Spin, notification } from 'antd'
import { get } from 'lodash'

import WrappedDynamicForm from '../../../../components/dynamicForm'
import { createEditBenefit } from './formData'
import { ShowBenefitGroupDataStyle } from './claimConfig.style'
import ClaimActions from '../../../redux/claims/actions'
import PropTypes from 'prop-types'
import errorAction from '../../../../redux/error/actions'
import loadingAction from '../../../../redux/loading/actions'

const { searchConfig, updateBenefit, addBenefitGroup } = ClaimActions
const { resetErrorRedux } = errorAction
const { resetLoadingRedux } = loadingAction

class CreateBenefit extends React.Component {
  constructor (props) {
    super(props)
    this.state = {
      edit_benefit_group_modal: false,
      view_benefit_modal: false,
      selectedBenefit: [],
      benefit_group_id: '',
      searchConfigResult: [],
      formValues: {},
      benefitGroupData: this.props.benefitGroupData,
      is_care_integration_enabled: false
    }

    this.dynamicForm = React.createRef()
  }

  componentDidMount () {
    const { benefitGroupData, benefitDetails } = this.props
    if (benefitGroupData) {
      this.setState({ benefitGroupData: benefitGroupData })
    }
    if (benefitDetails.care_integration_data) {
      const hasValue = benefitDetails.care_integration_data.col?.length > 0
      this.setState({ is_care_integration_enabled: hasValue })
    }
    this.props.resetErrorRedux(['BENEFIT_UPDATE', 'ADD_BENEFIT_GROUP'])
    this.props.resetLoadingRedux(['BENEFIT_UPDATE', 'ADD_BENEFIT_GROUP'])
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      benefitUpdateLoading, benefitUpdateError, benefitUpdateStatus,
      addBenefitGroupStatus, addBenefitGroupError, addBenefitGroupLoading, benefitGroupData, benefitDetails
    } = nextProps
    if (benefitDetails.care_integration_data) {
      const hasValue = benefitDetails.care_integration_data.col?.length > 0
      this.setState({ is_care_integration_enabled: hasValue })
    }
    if (addBenefitGroupLoading === false) {
      notification[addBenefitGroupError ? 'error' : 'success']({ message: addBenefitGroupStatus })
      if (addBenefitGroupError === false) {
        this.updateBenefit(benefitGroupData.benefit_group_id)
      }
      this.props.resetErrorRedux(['ADD_BENEFIT_GROUP'])
      this.props.resetLoadingRedux(['ADD_BENEFIT_GROUP'])
    }

    if (benefitUpdateLoading === false) {
      notification[benefitUpdateError ? 'error' : 'success']({ message: benefitUpdateStatus })
      const wrappedInstance = this.dynamicForm.current.getWrappedInstance()
      wrappedInstance.resetFields()
      if (benefitUpdateError === false) {
        this.props.onCancel('showEditBenefitModal')
      }
      this.props.resetErrorRedux(['BENEFIT_UPDATE'])
      this.props.resetLoadingRedux(['BENEFIT_UPDATE'])
    }
  }

  createBenefitGroup = () => {
    const { formValues } = this.state

    this.props.addBenefitGroup({
      is_active: formValues.is_claim_active,
      name: formValues.benefit_group_name,
      description: '',
      max_claim_amount: formValues.benefit_group_tsi,
      max_claim_allowed: formValues.benefit_group_number_of_times_claimable,
      product_key: JSON.parse(localStorage.getItem('data')).product,
      package_name: JSON.parse(localStorage.getItem('data')).package,
      insurance_provider: '',
      package_code: ''
    })
  }

  updateBenefit = () => {
    const { benefitDetails } = this.props
    const { formValues } = this.state

    delete formValues.benefit_group_tsi
    delete formValues.benefit_group_number_of_times_claimable
    delete formValues.benefit_group_name

    this.props.updateBenefit({
      benefit_group_id: get(benefitDetails, 'benefit_group.id'),
      benefit_id: benefitDetails.id,
      data: formValues
    })
  }

  onHandleCareIntegrationCheckbox = (e) => {
    if (e.target.id === 'is_care_integration_enabled') {
      this.setState({ is_care_integration_enabled: e.target.checked })
    }
  };

  onSubmit = (value) => {
    const { is_care_integration_enabled: isCareIntegrationEnabled, ...payload } = value
    this.setState({ formValues: payload },
      () => this.updateBenefit()
    )
  }

  render () {
    const { benefitUpdateLoading, benefitDetails = {}, selectedProduct, packageList, selectedPartner, selectedPackageCode } = this.props
    const { benefitGroupData, is_care_integration_enabled: isCareIntegrationEnabled } = this.state
    const {
      is_claim_active: isClaimActive,
      name,
      description,
      max_claim_allowed: maxClaimAllowed,
      claim_initiated_reject_day: claimInitiatedRejectDay,
      claim_reprocess_reject_day: claimReprocessRejectDay,
      claim_initiated_reminder_days: claimInitiatedReminderDays,
      benefit_group: benefitGroup = {},
      claim_reprocess_reminder_days: claimReprocessReminderDays,
      care_integration_data: careIntegrationData = {}
    } = benefitDetails

    const selectedProviderCode = packageList
      .filter(({ package_code: packageCodeFromList }) => packageCodeFromList === selectedPackageCode)
      .map(({ provider_code: providerCode }) => providerCode)?.[0]

    return (
      <ShowBenefitGroupDataStyle>
        <Spin spinning={!!benefitUpdateLoading}>
          <WrappedDynamicForm
            ref={this.dynamicForm}
            formData={
              createEditBenefit(
                'Edit Benefit',
                {},
                {
                  is_claim_active: isClaimActive,
                  name: name,
                  description: description,
                  max_claim_allowed: maxClaimAllowed,
                  claim_initiated_reject_day: claimInitiatedRejectDay,
                  claim_reprocess_reject_day: claimReprocessRejectDay,
                  claim_initiated_reminder_days: claimInitiatedReminderDays,
                  benefit_group_id: benefitGroup.id,
                  claim_reprocess_reminder_days: claimReprocessReminderDays,
                  ...careIntegrationData
                },
                {
                  benefitGroupData: benefitGroupData,
                  isBenefitType: false,
                  disabled: true,
                  selectedProviderCode,
                  selectedProduct,
                  selectedPartner,
                  selectedPackageCode,
                  is_care_integration_enabled: isCareIntegrationEnabled
                },
                false
              )
}
            handleCheckboxChange={this.onHandleCareIntegrationCheckbox}
            onCloseModal={() => this.props.onCancel('showEditBenefitModal')}
            onSubmit={(values) => this.onSubmit(values)}
          />
        </Spin>
      </ShowBenefitGroupDataStyle>
    )
  }
}

CreateBenefit.propTypes = {
  searchConfigResult: PropTypes.array.isRequired
}

CreateBenefit.defaultProps = {
  searchConfigResult: []
}
const WrappedCreateBenefit = Form.create()(CreateBenefit)

export default connect(state => ({
  searchConfigResult: state.Claims.searchConfigResult.configs,
  benefitUpdateLoading: state.Loading.BENEFIT_UPDATE,
  benefitUpdateError: state.Error.BENEFIT_UPDATE,
  benefitUpdateStatus: state.Claims.updateBenefitStatus,
  addBenefitGroupLoading: state.Loading.ADD_BENEFIT_GROUP,
  addBenefitGroupError: state.Error.ADD_BENEFIT_GROUP,
  addBenefitGroupStatus: state.Claims.addBenefitGroupStatus,
  benefitGroupData: state.Claims.benefitGroupData
}), {
  searchConfig,
  updateBenefit,
  addBenefitGroup,
  resetErrorRedux,
  resetLoadingRedux
})(WrappedCreateBenefit)
