import 'react-viewer/dist/index.css'
import React from 'react'
import { connect } from 'react-redux'
import { Form, Spin, notification } from 'antd'
import WrappedDynamicForm from '../../../../components/dynamicForm'
import { createEditBenefit } from './formData'
import { ShowBenefitGroupDataStyle } from './claimConfig.style'
import ClaimActions from '../../../redux/claims/actions'
import errorAction from '../../../../redux/error/actions'
import loadingAction from '../../../../redux/loading/actions'

const { benefitCreation, addBenefitGroup, getBenefitGroup } = ClaimActions
const { resetErrorRedux } = errorAction
const { resetLoadingRedux } = loadingAction

const BENEFIT_TYPE = [{ label: 'Auto benefit', val: 'AutoFSM' }, { label: 'B2B2C', val: 'CannyFSM' }]
class CreateBenefit extends React.Component {
  constructor (props) {
    super(props)
    this.state = {
      benefitGroupData: [],
      edit_benefit_group_modal: false,
      view_benefit_modal: false,
      selectedBenefit: [],
      benefit_group_id: '',
      formValues: {},
      is_care_integration_enabled: false
    }
    this.dynamicForm = React.createRef()
  }

  componentDidMount () {
    const { benefitGroupData } = this.props
    // let benefitGroupData = this.props.history.location.state ? this.props.history.location.state.benefitGroupData : null
    if (benefitGroupData) {
      this.setState({ benefitGroupData: benefitGroupData })
    }
    this.props.resetErrorRedux(['BENEFIT_CREATION', 'ADD_BENEFIT_GROUP'])
    this.props.resetLoadingRedux(['BENEFIT_CREATION', 'ADD_BENEFIT_GROUP'])
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      benefitCreationLoading,
      benefitCreationError,
      benefitCreationStatus,
      showCreateBenefitModal
    } = nextProps

    if (benefitCreationLoading === false) {
      if (benefitCreationError === false) {
        const { selectedProduct, selectedPackageCode } = this.props
        this.props.onCancel('showCreateBenefitModal')
        this.props.getBenefitGroup({ query: { 'product-key': selectedProduct, 'package-code': selectedPackageCode } })
      }
      notification[benefitCreationError ? 'error' : 'success']({ message: benefitCreationStatus })
      this.props.resetErrorRedux(['BENEFIT_CREATION'])
      this.props.resetLoadingRedux(['BENEFIT_CREATION'])
    }

    if (showCreateBenefitModal === false) {
      const wrappedInstance = this.dynamicForm.current.getWrappedInstance()
      wrappedInstance.resetFields()
    }
  }

  createBenefitGroup = () => {
    const { formValues } = this.state
    const { selectedProduct, selectedPackage, selectedPackageCode } = this.props

    this.props.addBenefitGroup({
      is_active: formValues.is_claim_active,
      name: formValues.benefit_group_name,
      description: '',
      max_claim_amount: formValues.benefit_group_tsi,
      max_claim_allowed: formValues.benefit_group_number_of_times_claimable,
      product_key: selectedProduct,
      package_name: selectedPackage,
      package_code: selectedPackageCode,
      insurance_provider: ''
    })
  }

  createBenefit = () => {
    const { selectedBenefitGroupID } = this.props
    const { formValues } = this.state
    delete formValues.benefit_group_tsi
    delete formValues.benefit_group_number_of_times_claimable
    delete formValues.benefit_group_name

    this.props.benefitCreation({
      benefit_group_id: selectedBenefitGroupID,
      data: formValues
    })
  }
  handleCareIntegrationCheckbox = (e) => {
    if(e.target.id==="is_care_integration_enabled"){
      this.setState({ is_care_integration_enabled: e.target.checked })
    }
  };

  handleSubmit = (value) => {
    if (value.AutoFSM !== true) {
      delete value.AutoFSM
    }
    const { is_care_integration_enabled, ...payload } = value; 
    this.setState({ formValues: payload },
      () => this.createBenefit()
    )
  }

  render () {
    const {
      benefitCreationLoading,
      packageList = [],
      selectedProduct,
      selectedPartner,
      selectedPackageCode
    } = this.props
    const { benefitGroupData,is_care_integration_enabled } = this.state
    const selectedProviderCode = packageList
      .filter(({ package_code: packageCodeFromList }) => packageCodeFromList === selectedPackageCode)
      .map(({ provider_code: providerCode }) => providerCode)?.[0]

    return (
      <ShowBenefitGroupDataStyle>
        <Spin spinning={benefitCreationLoading || false}>
          <WrappedDynamicForm
            ref={this.dynamicForm}
            formData={
              createEditBenefit(
                'Add Benefit',
                {},
                { is_claim_active: true },
                {
                  benefitGroupData: benefitGroupData,
                  benefitTypes: BENEFIT_TYPE,
                  isBenefitType: true,
                  selectedProviderCode,
                  selectedProduct,
                  selectedPartner,
                  selectedPackageCode,
                  is_care_integration_enabled,
                }
              )
            }
            onCloseModal={() => {
              this.props.onCancel('showCreateBenefitModal')
            }}
            onSubmit={this.handleSubmit}
            handleCheckboxChange={this.handleCareIntegrationCheckbox}
          />
        </Spin>
      </ShowBenefitGroupDataStyle>
    )
  }
}

const WrappedCreateBenefit = Form.create()(CreateBenefit)

export default connect(state => ({
  benefitCreationLoading: state.Loading.BENEFIT_CREATION,
  benefitCreationError: state.Error.BENEFIT_CREATION,
  benefitCreationStatus: state.Claims.benefitCreationStatus,

  addBenefitGroupLoading: state.Loading.ADD_BENEFIT_GROUP,
  addBenefitGroupError: state.Error.ADD_BENEFIT_GROUP,
  addBenefitGroupStatus: state.Claims.addBenefitGroupStatus,
  benefitGroupData: state.Claims.benefitGroupData
}), {
  benefitCreation,
  addBenefitGroup,
  resetErrorRedux,
  resetLoadingRedux,
  getBenefitGroup
})(WrappedCreateBenefit)
