export function createEditBenefitGroup (heading, additionalData, defaultValues = {}, data = {}) {
  return {
    heading: heading,
    fields: [{
      type: 'checkbox',
      value: defaultValues.is_active || false,
      label: 'Active',
      decorator: 'is_active',
      required: false
    }, {
      type: 'input',
      value: defaultValues.benefit_group_name,
      label: 'Benefit Group Name',
      decorator: 'name',
      required: true
    }, {
      type: 'textarea',
      value: defaultValues.description,
      label: 'Benefit Group Description',
      decorator: 'description',
      required: true
    }, {
      type: 'integer_input',
      value: defaultValues.number_of_times_claimable,
      label: 'Number of times claimable',
      decorator: 'max_claim_allowed',
      help: 'Set -1, if there is no limit on claims',
      required: true
    }, {
      type: 'select-default',
      value: defaultValues.max_claim_amount_type,
      label: 'TSI Type',
      decorator: 'max_claim_amount_type',
      data: data.tsiTypes,
      required: true
    }, {
      type: 'float_input',
      value: defaultValues.total_sum_insured,
      label: 'Total sum insured',
      decorator: 'max_claim_amount',
      required: true,
      condition: [{ key: 'max_claim_amount_type', value: 'FIXED' }]
    }, {
      type: 'select-tsi',
      value: defaultValues.tsi_method,
      label: 'TSI Method',
      decorator: 'max_claim_amount',
      required: true,
      data: data.tsiMethods,
      condition: [{ key: 'max_claim_amount_type', value: 'METHOD' }]
    }, {
      type: 'select-tsi',
      label: 'Select the amount calculation logic',
      value: defaultValues.type,
      decorator: 'type',
      required: true,
      data: [{
        display_name: 'Y percentage of policys X field',
        slug: 'Y-percentage-of-X-field-from-policy'
      }],
      condition: [{ key: 'max_claim_amount', value: 'automatic_calculation' }]
    }, {
      type: 'select-tsi',
      label: 'Select the field from policy need to be applied',
      value: defaultValues.field,
      decorator: 'field',
      required: true,
      data: data.policyFormAttributes,
      condition: [
        { key: 'max_claim_amount', value: 'automatic_calculation' },
        { key: 'type', value: 'Y-percentage-of-X-field-from-policy' }
      ]
    },
    {
      type: 'integer_input',
      label: 'Enter the percentage',
      decorator: 'percentage',
      value: defaultValues.percentage,
      required: true,
      condition: [
        { key: 'max_claim_amount', value: 'automatic_calculation' },
        { key: 'type', value: 'Y-percentage-of-X-field-from-policy' }
      ],
      rules: [{
        pattern: /^\s*(?=.*[1-9])\d*(?:\.\d{1,2})?\s*$/,
        message: 'Percentage could not be negative or zero'
      }]
    }
    ],
    buttons: [{
      htmlType: 'button',
      label: 'Cancel',
      type: 'danger'
    }, {
      htmlType: 'submit',
      label: 'Save',
      type: 'primary'
    }],
    additional_data: additionalData
  }
}

export function getCareIntegrationFormFields ({ defaultValues, isCareIntegrationEnabled = false }) {
  if ((isCareIntegrationEnabled)) {
    return ([
      {
        type: 'textarea',
        label: 'COL(Cause of loss)',
        value: defaultValues.col,
        decorator: 'col',
        required: true
      },
      {
        type: 'textarea',
        label: 'Damage Type',
        value: defaultValues.damage_type,
        required: true,
        decorator: 'damage_type'
      },
      {
        type: 'textarea',
        label: 'Enter the KOL',
        decorator: 'kol',
        value: defaultValues.kol
      },
      {
        type: 'textarea',
        label: 'Payment To',
        decorator: 'payment_to',
        value: defaultValues.payment_to
      },
      {
        type: 'textarea',
        label: 'Remarks',
        decorator: 'remarks',
        value: defaultValues.remarks
      },
      {
        type: 'textarea',
        label: 'TOI',
        decorator: 'toi',
        value: defaultValues.toi
      }
    ]
    )
  }

  return []
}

export function createEditBenefit (heading, additionalData, defaultValues = {}, data = {}) {
  const {
    selectedProviderCode,
    selectedProduct,
    selectedPartner,
    selectedPackageCode,
    is_care_integration_enabled: isCareIntegrationEnabled
  } = data
  return {
    heading: heading,
    fields: [{
      type: 'checkbox',
      value: defaultValues.is_claim_active || false,
      label: 'Active',
      decorator: 'is_claim_active',
      required: false
    },
    ...(data?.isBenefitType
      ? [{
          type: 'select-default',
          value: defaultValues.benefit_type,
          label: 'Benefit Type',
          decorator: 'type',
          data: data.benefitTypes,
          required: true,
          disabled: data?.disabled
        }]
      : []),
    {
      type: 'input',
      value: defaultValues.name,
      label: 'Benefit Name',
      decorator: 'name',
      required: true
    }, {
      type: 'textarea',
      value: defaultValues.description,
      label: 'Benefit Description',
      decorator: 'description',
      required: true
    }, {
      type: 'integer_input',
      value: defaultValues.display_order,
      label: 'Display Order',
      decorator: 'display_order',
      required: false
    }, {
      type: 'integer_input',
      value: defaultValues.max_claim_allowed,
      label: 'Max Claim Allowed',
      decorator: 'max_claim_allowed',
      required: true
    }, {
      type: 'integer_input',
      value: defaultValues.claim_initiated_reject_day,
      label: 'Claim initiated reject day',
      decorator: 'claim_initiated_reject_day',
      help: 'Enter the number of days after which claim will get auto rejected from initiated state',
      required: false
    }, {
      type: 'integer_input',
      value: defaultValues.claim_reprocess_reject_day,
      label: 'Claim reprocess reject day',
      decorator: 'claim_reprocess_reject_day',
      help: 'Enter the number of days after which claim will get auto rejected from reprocess state',
      required: false
    }, {
      type: 'input',
      value: defaultValues.claim_initiated_reminder_days,
      label: 'Claim initiated reminder days',
      decorator: 'claim_initiated_reminder_days',
      required: false,
      help: 'e.g. 1, 5, 7, 9',
      parseToArray: true
    }, {
      type: 'input',
      value: defaultValues.claim_reprocess_reminder_days,
      label: 'Claim reprocess reminder days',
      decorator: 'claim_reprocess_reminder_days',
      required: false,
      help: 'e.g. 1, 5, 7, 9',
      parseToArray: true
    },
    {
      type: 'checkbox',
      value: isCareIntegrationEnabled,
      label: 'Is Care integration enabled',
      decorator: 'is_care_integration_enabled',
      required: false
    },
    ...getCareIntegrationFormFields({ defaultValues, selectedProviderCode, selectedProduct, selectedPartner, selectedPackageCode, isCareIntegrationEnabled })
    ],
    buttons: [{
      htmlType: 'button',
      label: 'Cancel',
      type: 'danger'
    }, {
      htmlType: 'submit',
      label: 'Save',
      type: 'primary'
    }],
    additional_data: additionalData
  }
}
